const qa_monster_creature_entry *qa_monster_source_creature(
    const qa_monster_source_definition *source, const char *classname) {
  for (size_t i = 0; i < source->creature_count; i++)
    if (strcmp(source->creatures[i].classname, classname) == 0)
      return &source->creatures[i];
  return NULL;
}

const qa_monster_source_definition *qa_monster_source(
    qa_monster_definition_reference definition) {
  const qa_monster_source_definition *source = NULL;
  for (size_t i = 0; i < qa_monster_source_count; i++)
    if (strcmp(qa_monster_sources[i].provider, definition.source.provider) == 0) {
      source = &qa_monster_sources[i];
      break;
    }
  if (source == NULL || qa_monster_source_creature(source, definition.classname) == NULL)
    qa_range_error("Selected monster implementation is unavailable: %s/%s",
                   definition.source.provider, definition.classname);
  return source;
}

qa_provider_timing qa_monster_timing(const qa_monster_source_definition *source) {
  qa_provider_timing timing;
  memset(&timing, 0, sizeof timing);
  timing.provider = source->provider;
  if (strcmp(source->family, "q1") == 0) {
    timing.numeric = qa_q1_donor_profile;
    timing.clock.kind = QA_CLOCK_Q1_NETQUAKE;
    timing.clock.minimum_frame_seconds = 0.001;
    timing.clock.maximum_frame_seconds = 0.1;
    timing.clock.has_fixed_frame_seconds = false; /* TS fixedFrameSeconds: null */
  } else if (strcmp(source->edition, "classic") == 0) {
    timing.numeric = qa_q2_donor_profile;
    timing.clock.kind = QA_CLOCK_Q2_CLASSIC;
    timing.clock.frame_milliseconds = 100;
  } else {
    timing.numeric = qa_q2_donor_profile;
    timing.clock.kind = QA_CLOCK_Q2_RERELEASE;
    timing.clock.frame_milliseconds = 25; /* TS preparation: "before-frame" */
  }
  return timing;
}
